import torch
import torch.nn as nn
from torch.utils.checkpoint import checkpoint

class ResBlock(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(dim, dim), nn.ReLU(), nn.Linear(dim, dim))

    def forward(self, x):
        return x + self.net(x)

class DeepResNet(nn.Module):
    def __init__(self, dim, n_blocks, use_checkpoint=False):
        super().__init__()
        self.blocks = nn.ModuleList([ResBlock(dim) for _ in range(n_blocks)])
        self.use_checkpoint = use_checkpoint

    def forward(self, x):
        for block in self.blocks:
            if self.use_checkpoint and self.training:
                # use_reentrant=False is the modern recommended mode
                x = checkpoint(block, x, use_reentrant=False)
            else:
                x = block(x)
        return x


def measure_peak_memory(use_checkpoint):
    torch.cuda.reset_peak_memory_stats()
    model = DeepResNet(dim=1024, n_blocks=50, use_checkpoint=use_checkpoint).cuda()
    x = torch.randn(64, 1024, device='cuda', requires_grad=True)
    out = model(x)
    loss = out.sum()
    loss.backward()
    return torch.cuda.max_memory_allocated() / 1e6  # MB

if torch.cuda.is_available():
    mem_no_ckpt = measure_peak_memory(False)
    mem_ckpt = measure_peak_memory(True)
    print(f'No checkpointing: {mem_no_ckpt:.1f} MB')
    print(f'With checkpointing: {mem_ckpt:.1f} MB')

import torch
from torch.utils.data import Dataset, DataLoader, Subset

class ToyTextDataset(Dataset):
    def __init__(self, sequences):
        self.sequences = sequences  # list of tensors of varying length

    def __len__(self):
        return len(self.sequences)

    def __getitem__(self, idx):
        return self.sequences[idx]


def curriculum_indices_by_length(dataset):
    # difficulty = sequence length (proxy for difficulty)
    lengths = [len(seq) for seq in dataset.sequences]
    return sorted(range(len(dataset)), key=lambda i: lengths[i])


def curriculum_train(model, dataset, optimizer, loss_fn, total_epochs=10, start_frac=0.2):
    sorted_idx = curriculum_indices_by_length(dataset)
    n = len(sorted_idx)

    for epoch in range(total_epochs):
        # linearly grow the fraction of (easy-to-hard) data available, from start_frac to 1.0
        frac = min(1.0, start_frac + (1.0 - start_frac) * epoch / max(1, total_epochs - 1))
        cutoff = max(1, int(n * frac))
        curr_indices = sorted_idx[:cutoff]

        subset = Subset(dataset, curr_indices)
        loader = DataLoader(subset, batch_size=8, shuffle=True,
                             collate_fn=lambda batch: batch)  # simple collate for variable length

        for batch in loader:
            optimizer.zero_grad()
